"""Differential fuzz: old HEAD implementation vs refactored package.

For every generated (base, chart, vouchers) triple both implementations
must agree exactly: same leaf exception type and message bytes, or equal
success payloads. Inputs must be untouched by both.
"""
import copy
import json
import random
import sys

sys.path.insert(0, "/tmp/old_ledger")
sys.path.insert(0, "/mnt/c/editf/luo9/B/echo004")

import old_ledger_engine as old  # noqa: E402
import ledger_engine as new  # noqa: E402

JSON_KW = {"sort_keys": True, "ensure_ascii": False, "separators": (",", ":")}

rng = random.Random(20240229)

BAD_DATES = ["2023-02-29", "2100-02-29", "2024-02-30", "2024-13-01",
             "2024-00-10", "2024-1-01", "2024/02/29", "20240229", None, True]
BAD_AMOUNTS = ["-1", "+1", "1e3", "1,000.00", " 100", "100 ", ".5", "1.",
               "1.234", "", "  ", "nan", "0x10", "1_000", "1.2.3", 0, 1,
               1.5, True, False, None, [100], {"v": 1}]
BAD_IDS = [123, None, True, "", b"V", ("V",)]
BAD_STR = [None, 7, True, 1.5]
FOREIGN = ["USD", "usd", "RMB", " CNY", "CNY ", "CN", "CNYY"]
CODES = ["1001", "2202", "6601"]
SUMMARIES = ["业务", "x", "购办公用品", ""]
GOOD_AMOUNTS = ["1", "0.1", "0.01", "100", "100.0", "100.00", "0", "00",
                "0.0", "0.00", "99999999999999999999.99", "1234.5", "7"]


def chart():
    return [
        {"code": "1001", "name": "库存现金", "normal_side": "debit",
         "active": True},
        {"code": "2202", "name": "应付账款", "normal_side": "credit",
         "active": True},
        {"code": "6601", "name": "管理费用", "normal_side": "debit",
         "active": True},
        {"code": "4001", "name": "停用收入", "normal_side": "credit",
         "active": False},
    ]


def entry(code=None, summary=None, d=None, c=None):
    return {"account_code": code or rng.choice(CODES),
            "summary": rng.choice(SUMMARIES) if summary is None else summary,
            "debit": d if d is not None else rng.choice(GOOD_AMOUNTS),
            "credit": c if c is not None else rng.choice(GOOD_AMOUNTS)}


def balanced_voucher(vid, date_text="2024-01-01", currency="CNY", n=None):
    """Build a structurally/business valid balanced voucher."""
    k = n or rng.choice([2, 2, 3, 4])
    total = rng.randint(1, 500000)
    entries = []
    # split total across debit-side entries then credit-side entries
    cuts = sorted(rng.sample(range(1, total), k - 1)) if total >= k else None
    if cuts is None:
        # fallback simple equal split via cents strings
        parts = [total // k] * k
        for i in range(total % k):
            parts[i] += 1
    else:
        parts = [cuts[0]] + [b - a for a, b in zip(cuts, cuts[1:])] + \
                [total - cuts[-1]]
    half = max(1, k // 2)
    for i, cents in enumerate(parts):
        if i < half:
            entries.append(entry(rng.choice(CODES), d=f"{cents // 100}.{cents % 100:02d}",
                                 c="0.00"))
        else:
            entries.append(entry(rng.choice(CODES), d="0.00",
                                 c=f"{cents // 100}.{cents % 100:02d}"))
    return {"voucher_id": vid, "date": date_text, "currency": currency,
            "entries": entries}


def mutate(base, ch, batch):
    """Apply 0..3 random mutations in place."""
    for _ in range(rng.randint(0, 3)):
        kind = rng.randrange(24)
        if kind == 0:
            return rng.choice(["bad", None, 1, True, ["CNY"]]), ch, batch
        if kind == 1 and isinstance(ch, list) and ch:
            i = rng.randrange(len(ch))
            mut = rng.randrange(5)
            if mut == 0:
                ch[i] = "not-object"
            elif mut == 1:
                f = rng.choice(["code", "name", "normal_side", "active"])
                del ch[i][f]
            elif mut == 2:
                ch[i]["code"] = rng.choice(["", 1, None])
            elif mut == 3:
                ch[i]["normal_side"] = rng.choice(["Debit", "", None, 0])
            else:
                ch.append(dict(ch[i]))
        elif kind == 2:
            ch = rng.choice([None, {}, tuple(ch), "chart"])
        elif kind == 3:
            return base, ch, rng.choice([None, {}, tuple(), "batch", 42])
        elif not isinstance(batch, list) or not batch:
            continue
        elif kind == 4:
            vi = rng.randrange(len(batch))
            batch[vi] = rng.choice(["x", None, 42, ["list"]])
        elif kind == 5:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                f = rng.choice(["voucher_id", "date", "currency", "entries"])
                batch[vi].pop(f, None)
        elif kind == 6:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                batch[vi]["voucher_id"] = rng.choice(BAD_IDS)
        elif kind == 7:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                batch[vi]["date"] = rng.choice(BAD_DATES)
        elif kind == 8:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                batch[vi]["currency"] = rng.choice(BAD_STR)
        elif kind == 9:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                batch[vi]["currency"] = rng.choice(FOREIGN)
        elif kind == 10:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict):
                batch[vi]["entries"] = rng.choice([None, "e", tuple(), [],
                                                   [entry()]])
        elif kind == 11 and len(batch) >= 1:
            vj = rng.randrange(len(batch))
            if isinstance(batch[vj], dict) and isinstance(batch[vj].get("entries"),
                                                          list) and batch[vj]["entries"]:
                ei = rng.randrange(len(batch[vj]["entries"]))
                batch[vj]["entries"][ei] = rng.choice(["e", None, 5])
        elif kind == 12:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict) and isinstance(batch[vi].get("entries"),
                                                          list) and batch[vi]["entries"]:
                ei = rng.randrange(len(batch[vi]["entries"]))
                if isinstance(batch[vi]["entries"][ei], dict):
                    f = rng.choice(["account_code", "summary", "debit", "credit"])
                    batch[vi]["entries"][ei].pop(f, None)
        elif kind == 13:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict) and isinstance(batch[vi].get("entries"),
                                                          list) and batch[vi]["entries"]:
                ei = rng.randrange(len(batch[vi]["entries"]))
                if isinstance(batch[vi]["entries"][ei], dict):
                    batch[vi]["entries"][ei]["account_code"] = rng.choice(
                        [1001, None, True, 10.01])
        elif kind == 14:
            vi = rng.randrange(len(batch))
            if isinstance(batch[vi], dict) and isinstance(batch[vi].get("entries"),
                                                          list) and batch[vi]["entries"]:
                ei = rng.randrange(len(batch[vi]["entries"]))
                if isinstance(batch[vi]["entries"][ei], dict):
